changeSet.sql:
DECLARE @Platform UNIQUEIDENTIFIER = '33333333-3333-4333-8333-333333333001';
DECLARE @Now DATETIME2 = SYSUTCDATETIME();

-- 1. Allow the Platform type while still tolerating legacy Personal rows during the backfill.
ALTER TABLE app.Tenants DROP CONSTRAINT CK_Tenants_TenantType;
ALTER TABLE app.Tenants ADD CONSTRAINT CK_Tenants_TenantType
    CHECK (TenantType IN (N'Platform', N'Personal', N'Gym', N'YogaStudio', N'CrossFit', N'Physio', N'Corporate'));

-- 2. Seed the single platform tenant.
IF NOT EXISTS (SELECT 1 FROM app.Tenants WHERE Id = @Platform)
    INSERT INTO app.Tenants (Id, Name, TenantType, Status, OwnerUserId, CreatedAt, UpdatedAt)
    VALUES (@Platform, N'LifeFit AI', N'Platform', N'Active', NULL, @Now, @Now);

-- 3. Restricted normal-user role: own data and business creation only; no member-read/update.
IF NOT EXISTS (SELECT 1 FROM app.Roles WHERE Name = N'PersonalMember')
    INSERT INTO app.Roles (Id, Name, Description, CreatedAt, UpdatedAt)
    VALUES ('11111111-1111-4111-8111-111111111008', N'PersonalMember',
        N'Normal user of the platform tenant. Manages only their own data.', @Now, @Now);

INSERT INTO app.RolePermissions (RoleId, PermissionId)
SELECT r.Id, p.Id
FROM app.Roles r
JOIN app.Permissions p ON p.Code IN (
    N'USER_READ', N'USER_UPDATE', N'TENANT_READ', N'TENANT_CREATE', N'LICENSE_READ', N'FEATURE_READ',
    N'FITNESS_READ', N'FITNESS_MANAGE', N'EXERCISE_READ', N'EXERCISE_MANAGE',
    N'WORKOUT_READ', N'WORKOUT_MANAGE', N'NUTRITION_READ', N'NUTRITION_MANAGE',
    N'AI_USE', N'CHALLENGE_READ', N'CHALLENGE_MANAGE', N'NOTIFICATION_READ')
WHERE r.Name = N'PersonalMember'
  AND NOT EXISTS (SELECT 1 FROM app.RolePermissions rp WHERE rp.RoleId = r.Id AND rp.PermissionId = p.Id);

-- 4. One personal license on the platform tenant; normal users inherit it.
IF NOT EXISTS (SELECT 1 FROM app.TenantLicenses WHERE TenantId = @Platform AND Status = N'Active' AND DeletedAt IS NULL)
BEGIN
    DECLARE @LicenseId UNIQUEIDENTIFIER = NEWID();
    DECLARE @PlanId UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM app.Plans WHERE Code = N'PERSONAL_FREE' AND DeletedAt IS NULL);
    DECLARE @BaseCap INT = (SELECT TOP 1 BaseCapacity FROM app.Plans WHERE Code = N'PERSONAL_FREE' AND DeletedAt IS NULL);
    INSERT INTO app.TenantLicenses (Id, TenantId, [Plan], Status, StartsAt, CreatedAt, UpdatedAt, PlanDefinitionId, BaseCapacity)
    VALUES (@LicenseId, @Platform, N'Free', N'Active', @Now, @Now, @Now, @PlanId, ISNULL(@BaseCap, 0));

    INSERT INTO app.FeatureFlags (Id, LicenseId, FeatureCode, [Enabled], CreatedAt, UpdatedAt)
    SELECT NEWID(), @LicenseId, fd.Code, ISNULL(pf.[Enabled], 0), @Now, @Now
    FROM app.FeatureDefinitions fd
    LEFT JOIN app.PlanFeatures pf ON pf.PlanId = @PlanId AND pf.FeatureCode = fd.Code
    WHERE fd.DeletedAt IS NULL;
END

-- 5. Backfill every legacy personal tenant into the platform tenant.
SELECT Id INTO #PersonalTenants FROM app.Tenants WHERE TenantType = N'Personal';

DECLARE @PersonalOwnerRole UNIQUEIDENTIFIER = (SELECT Id FROM app.Roles WHERE Name = N'PersonalOwner' AND DeletedAt IS NULL);
DECLARE @PersonalMemberRole UNIQUEIDENTIFIER = (SELECT Id FROM app.Roles WHERE Name = N'PersonalMember' AND DeletedAt IS NULL);

-- Move role assignments to the platform tenant and downgrade PersonalOwner to PersonalMember.
UPDATE ur
SET ur.TenantId = @Platform,
    ur.RoleId = CASE WHEN ur.RoleId = @PersonalOwnerRole THEN @PersonalMemberRole ELSE ur.RoleId END,
    ur.UpdatedAt = @Now
FROM app.UserRoles ur
WHERE ur.TenantId IN (SELECT Id FROM #PersonalTenants);

UPDATE tm SET tm.TenantId = @Platform, tm.UpdatedAt = @Now
FROM app.TenantMembers tm WHERE tm.TenantId IN (SELECT Id FROM #PersonalTenants);

-- Fitness, nutrition, AI, challenge, notification, measurement, audit, and idempotency rows.
UPDATE t SET t.TenantId = @Platform FROM app.FitnessProfiles t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.FitnessGoals t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.BodyMeasurements t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.BodyScanRecords t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.WorkoutPrograms t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.WorkoutSessions t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.NutritionProfiles t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.NutritionLogs t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.AiConversations t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.AiUsageRecords t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.Challenges t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.ChallengeParticipants t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.Notifications t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.Exercises t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.AuditLogs t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);
UPDATE t SET t.TenantId = @Platform FROM app.IdempotencyRecords t WHERE t.TenantId IN (SELECT Id FROM #PersonalTenants);

-- Any stray license artifacts that pointed at a personal tenant.
DELETE FROM app.UserLicenseAssignments WHERE TenantId IN (SELECT Id FROM #PersonalTenants);
DELETE FROM app.LicenseOverrides WHERE TenantId IN (SELECT Id FROM #PersonalTenants);

-- Point each user's home tenant at the platform tenant.
UPDATE u SET u.TenantId = @Platform, u.UpdatedAt = @Now
FROM app.Users u WHERE u.TenantId IN (SELECT Id FROM #PersonalTenants);

-- Drop the per-user personal licenses and the now-empty personal tenants.
DELETE ff FROM app.FeatureFlags ff
JOIN app.TenantLicenses tl ON tl.Id = ff.LicenseId
WHERE tl.TenantId IN (SELECT Id FROM #PersonalTenants);
DELETE lcg FROM app.LicenseCapacityGrants lcg
JOIN app.TenantLicenses tl ON tl.Id = lcg.TenantLicenseId
WHERE tl.TenantId IN (SELECT Id FROM #PersonalTenants);
DELETE FROM app.TenantLicenses WHERE TenantId IN (SELECT Id FROM #PersonalTenants);
DELETE FROM app.Tenants WHERE Id IN (SELECT Id FROM #PersonalTenants);

DROP TABLE #PersonalTenants;

-- 6. Forbid the Personal type now that no personal tenants remain.
ALTER TABLE app.Tenants DROP CONSTRAINT CK_Tenants_TenantType;
ALTER TABLE app.Tenants ADD CONSTRAINT CK_Tenants_TenantType
    CHECK (TenantType IN (N'Platform', N'Gym', N'YogaStudio', N'CrossFit', N'Physio', N'Corporate'));

rollback.sql:
-- Schema rollback only. The personal-tenant split cannot be reconstructed from the merged rows.
DECLARE @Platform UNIQUEIDENTIFIER = '33333333-3333-4333-8333-333333333001';
ALTER TABLE app.Tenants DROP CONSTRAINT CK_Tenants_TenantType;
ALTER TABLE app.Tenants ADD CONSTRAINT CK_Tenants_TenantType
    CHECK (TenantType IN (N'Personal', N'Gym', N'YogaStudio', N'CrossFit', N'Physio', N'Corporate'));

DELETE ff FROM app.FeatureFlags ff
JOIN app.TenantLicenses tl ON tl.Id = ff.LicenseId
WHERE tl.TenantId = @Platform;
DELETE FROM app.TenantLicenses WHERE TenantId = @Platform;

DELETE FROM app.RolePermissions
WHERE RoleId = (SELECT Id FROM app.Roles WHERE Name = N'PersonalMember');
DELETE FROM app.Roles WHERE Name = N'PersonalMember';
DELETE FROM app.Tenants WHERE Id = @Platform;
